DECLARE
  ret1 INT;
BEGIN
  WITH p AS PROCEDURE (a INT)
    RETURNS INT
    LANGUAGE SQL
    AS 'BEGIN RETURN a; END;'
  CALL p(1) INTO :ret1;
  RETURN ret1;
END;

